namespace Awl { partial class Shell {
 void StyleSlider(Slider slider){slider.Loaded+=delegate{var track=slider.Template.FindName("PART_Track",slider) as Track;if(track!=null&&track.Thumb!=null){var t=new ControlTemplate(typeof(Thumb));var dot=new FrameworkElementFactory(typeof(Border));dot.SetValue(Border.BackgroundProperty,accentBrush);dot.SetValue(Border.CornerRadiusProperty,new CornerRadius(7));t.VisualTree=dot;track.Thumb.Template=t;track.Thumb.Width=14;track.Thumb.Height=14;}};slider.IsMoveToPointEnabled=true;}
 string appSort="Name",barTab="Top bar",appQuery="";bool appSettingsSearch,displayScaleExpanded;
 string ShortPath(string value){return String.IsNullOrEmpty(value)?"":value.Length>24?value.Substring(0,24)+"...":value;}
 string NormalizeAppText(string value){return new string((value??"").ToLowerInvariant().Select(c=>Char.IsLetterOrDigit(c)?c:' ').ToArray());}
 int SearchRank(AppEntry entry){string query=NormalizeAppText(appQuery).Trim(),name=NormalizeAppText(entry.Name).Trim(),target=NormalizeAppText(entry.Target).Trim();if(name==query)return 0;if(name.StartsWith(query))return 1;if(name.Contains(query))return 2;if(target.Contains(query))return 3;return 9;}
 bool MatchesApp(AppEntry entry){return String.IsNullOrWhiteSpace(appQuery)||SearchRank(entry)<9;}
 long AppSortTicks(AppEntry entry){long value;if(cfg.LastLaunch.TryGetValue(entry.Target,out value)&&value>0)return value;try{return File.GetLastWriteTimeUtc(entry.Target).Ticks;}catch{return 0;}}
 IEnumerable<AppEntry> OrderedAppResults(){IEnumerable<AppEntry> entries=catalog.Where(MatchesApp);if(!String.IsNullOrWhiteSpace(appQuery))return entries.OrderBy(SearchRank).ThenBy(x=>x.Name,StringComparer.CurrentCultureIgnoreCase);if(appSort=="Recent")return entries.OrderByDescending(AppSortTicks).ThenBy(x=>x.Name,StringComparer.CurrentCultureIgnoreCase);if(appSort=="Most used")return entries.OrderByDescending(x=>cfg.LaunchCounts.ContainsKey(x.Target)?cfg.LaunchCounts[x.Target]:0).ThenByDescending(AppSortTicks).ThenBy(x=>x.Name,StringComparer.CurrentCultureIgnoreCase);return entries.OrderBy(x=>x.Name,StringComparer.CurrentCultureIgnoreCase);}
 Tuple<string,string,string>[] WindowsSettings(){return new[]{Tuple.Create("System","Display, sound, notifications, power, storage","ms-settings:system"),Tuple.Create("Display","Brightness, scale, resolution, graphics","ms-settings:display"),Tuple.Create("Sound","Volume, output, input, microphone","ms-settings:sound"),Tuple.Create("Notifications","Alerts, banners, do not disturb","ms-settings:notifications"),Tuple.Create("Power & battery","Sleep, energy, battery usage","ms-settings:powersleep"),Tuple.Create("Storage","Disk, cleanup, storage spaces","ms-settings:storagesense"),Tuple.Create("Bluetooth & devices","Bluetooth, mouse, keyboard, printers","ms-settings:bluetooth"),Tuple.Create("Network & internet","Wi-Fi, Ethernet, VPN, hotspot","ms-settings:network"),Tuple.Create("Personalization","Wallpaper, colors, themes, lock screen","ms-settings:personalization"),Tuple.Create("Apps","Installed apps, defaults, startup apps","ms-settings:appsfeatures"),Tuple.Create("Accounts","Profile, sign-in, users, backup","ms-settings:accounts"),Tuple.Create("Time & language","Date, time, region, typing","ms-settings:dateandtime"),Tuple.Create("Gaming","Game Bar, captures, Game Mode","ms-settings:gaming-gamebar"),Tuple.Create("Accessibility","Text size, contrast, narrator, captions","ms-settings:easeofaccess"),Tuple.Create("Privacy & security","Permissions, camera, microphone, security","ms-settings:privacy"),Tuple.Create("Windows Update","Updates, update history, recovery","ms-settings:windowsupdate"),Tuple.Create("Taskbar","Taskbar behavior and system tray","ms-settings:taskbar"),Tuple.Create("About","Device specifications and Windows version","ms-settings:about")};}
 IEnumerable<Tuple<string,string,string>> MatchingWindowsSettings(){string query=NormalizeAppText(appQuery).Trim();return WindowsSettings().Where(x=>String.IsNullOrEmpty(query)||NormalizeAppText(x.Item1+" "+x.Item2).Contains(query)).OrderBy(x=>NormalizeAppText(x.Item1).StartsWith(query)?0:1).ThenBy(x=>x.Item1);}
 void OpenTopSearchResult(){if(appSettingsSearch){var setting=MatchingWindowsSettings().FirstOrDefault();if(setting!=null){if(launcher!=null)launcher.Hide();Launch(setting.Item3);}return;}var app=DockEntries().Concat(cfg.StartPins).Where(MatchesApp).GroupBy(x=>x.Target,StringComparer.OrdinalIgnoreCase).Select(x=>x.First()).FirstOrDefault()??OrderedAppResults().FirstOrDefault();if(app!=null)OpenApp(app);}
 string SearchKeyText(KeyEventArgs e){Key key=e.Key==Key.System?e.SystemKey:e.Key;if(key>=Key.A&&key<=Key.Z)return ((char)('a'+(key-Key.A))).ToString();if(key>=Key.D0&&key<=Key.D9)return ((char)('0'+(key-Key.D0))).ToString();if(key>=Key.NumPad0&&key<=Key.NumPad9)return ((char)('0'+(key-Key.NumPad0))).ToString();return key==Key.Space?" ":"";}
 void InsertSearchText(TextBox box,string value){int start=box.SelectionStart,length=box.SelectionLength;box.Text=box.Text.Remove(start,length).Insert(start,value);box.SelectionStart=start+value.Length;}
 public string AppSearchSelfTest(){appQuery="Godot v4.7.2 stable win64";if(!MatchesApp(new AppEntry{Name="Godot_v4.7.2-stable_win64.exe",Target="C:\\Apps\\Godot_v4.7.2-stable_win64.exe"}))return "FAILED: punctuated Godot search";appQuery="steam";if(!MatchesApp(new AppEntry{Name="Steam",Target="C:\\Program Files\\Steam\\steam.exe"}))return "FAILED: Steam search";appQuery="bluetooth";if(MatchingWindowsSettings().FirstOrDefault()==null)return "FAILED: Windows Settings search";return "App and Windows Settings search handle names, separators, versions, and paths";}
 Border Card(string title,Action body){var old=page;var contents=new StackPanel();page=contents;if(title!=""){var heading=Text(title,13);heading.FontWeight=FontWeights.SemiBold;heading.Margin=new Thickness(0,0,0,16);contents.Children.Add(heading);}body();page=old;return new Border{Background=new SolidColorBrush(Mix(baseColor,Colors.White,light?.06:.035)),BorderBrush=new SolidColorBrush(Mix(baseColor,Colors.White,.12)),BorderThickness=new Thickness(1),CornerRadius=new CornerRadius(16),Padding=new Thickness(20),Margin=new Thickness(0,0,0,16),Child=contents};}
