 void Setting(string label,bool value,Action<bool> change,string detail=null){var box=new StackPanel{Margin=new Thickness(0,4,0,8)};box.Children.Add(Switch(label,value,change));if(detail!=null)box.Children.Add(Text(detail,11,mutedBrush));box.Children.Add(new Border{Height=1,Background=cardBrush,Margin=new Thickness(0,10,0,0)});page.Children.Add(box);}
