 double SurfaceOverride(string name){return name=="Taskbar"?cfg.TaskbarScale:name=="Start menu"?cfg.StartMenuScale:name=="Pinned column"?cfg.PinnedBarScale:name=="Pinned grid"?cfg.PinnedGridScale:name=="Notification panel"?cfg.NotificationScale:name=="Top toolbar"?cfg.TopToolbarScale:name=="Battery popup"?cfg.BatteryPopupScale:name=="Volume popup"?cfg.VolumePopupScale:name=="Microphone popup"?cfg.MicrophonePopupScale:name=="Brightness popup"?cfg.BrightnessPopupScale:name=="Bluetooth popup"?cfg.BluetoothPopupScale:name=="Capture chooser"?cfg.CaptureToolScale:name=="Recording controls"?cfg.CaptureRecorderScale:name=="Capture review"?cfg.CaptureReviewScale:name=="Wi-Fi panel"?cfg.WifiScale:cfg.WidgetScale;}
 double SurfaceScale(string name){double value=SurfaceOverride(name);return Clamp(value>0?value:cfg.GuiScale,.7,1.5);}
 void ApplySurfaceScale(FrameworkElement element,string name){double value=SurfaceScale(name);element.LayoutTransform=Math.Abs(value-1)<.001?Transform.Identity:new ScaleTransform(value,value);}
 public string GuiScaleSelfTest(){double global=cfg.GuiScale,taskbar=cfg.TaskbarScale;try{cfg.GuiScale=1.2;cfg.TaskbarScale=0;if(Math.Abs(SurfaceScale("Taskbar")-1.2)>.001)return "FAILED: follow global scale";cfg.TaskbarScale=.85;if(Math.Abs(SurfaceScale("Taskbar")-.85)>.001)return "FAILED: per-surface scale";return "GUI scale follows global and honors individual overrides";}finally{cfg.GuiScale=global;cfg.TaskbarScale=taskbar;}}
 void SetSurfaceScale(string name,double value){if(name=="Taskbar")cfg.TaskbarScale=value;else if(name=="Start menu")cfg.StartMenuScale=value;else if(name=="Pinned column")cfg.PinnedBarScale=value;else if(name=="Pinned grid")cfg.PinnedGridScale=value;else if(name=="Notification panel")cfg.NotificationScale=value;else if(name=="Top toolbar")cfg.TopToolbarScale=value;else if(name=="Battery popup")cfg.BatteryPopupScale=value;else if(name=="Volume popup")cfg.VolumePopupScale=value;else if(name=="Microphone popup")cfg.MicrophonePopupScale=value;else if(name=="Brightness popup")cfg.BrightnessPopupScale=value;else if(name=="Bluetooth popup")cfg.BluetoothPopupScale=value;else if(name=="Capture chooser")cfg.CaptureToolScale=value;else if(name=="Recording controls")cfg.CaptureRecorderScale=value;else if(name=="Capture review")cfg.CaptureReviewScale=value;else if(name=="Wi-Fi panel")cfg.WifiScale=value;else cfg.WidgetScale=value;}
 bool ToolbarScaleVisible(string surface){string module=surface=="Battery popup"?"Battery":surface=="Volume popup"?"Volume":surface=="Microphone popup"?"Microphone":surface=="Brightness popup"?"Brightness":surface=="Wi-Fi panel"?"Network":surface=="Bluetooth popup"?"Bluetooth":"Notifications";return cfg.ShowTop&&!cfg.HiddenModules.Contains(module);}
 void StyleScaleInput(TextBox input){input.Width=76;input.Height=54;input.Padding=new Thickness(10,0,10,0);input.HorizontalContentAlignment=HorizontalAlignment.Center;input.VerticalContentAlignment=VerticalAlignment.Center;input.FontSize=15;var template=new ControlTemplate(typeof(TextBox));var border=new FrameworkElementFactory(typeof(Border));border.SetValue(Border.BackgroundProperty,new TemplateBindingExtension(Control.BackgroundProperty));border.SetValue(Border.BorderBrushProperty,new TemplateBindingExtension(Control.BorderBrushProperty));border.SetValue(Border.BorderThicknessProperty,new TemplateBindingExtension(Control.BorderThicknessProperty));border.SetValue(Border.CornerRadiusProperty,new CornerRadius(13));border.SetValue(Border.PaddingProperty,new TemplateBindingExtension(Control.PaddingProperty));var content=new FrameworkElementFactory(typeof(ScrollViewer));content.Name="PART_ContentHost";border.AppendChild(content);template.VisualTree=border;input.Template=template;}
