  var globalHeader=new DockPanel();var globalValue=Text(Math.Round(cfg.GuiScale*100)+"%",15,accentBrush);globalValue.FontWeight=FontWeights.SemiBold;DockPanel.SetDock(globalValue,Dock.Right);globalHeader.Children.Add(globalValue);var globalTitle=Text("Global scale",15);globalTitle.FontWeight=FontWeights.SemiBold;globalHeader.Children.Add(globalTitle);page.Children.Add(globalHeader);
