  var section=new DockPanel{Margin=new Thickness(0,24,0,10)};var reset=Action("Reset all",()=>{cfg.TaskbarScale=cfg.StartMenuScale=cfg.PinnedBarScale=cfg.PinnedGridScale=cfg.NotificationScale=cfg.TopToolbarScale=cfg.WifiScale=cfg.WidgetScale=cfg.BatteryPopupScale=cfg.VolumePopupScale=cfg.MicrophonePopupScale=cfg.BrightnessPopupScale=cfg.BluetoothPopupScale=cfg.CaptureToolScale=cfg.CaptureRecorderScale=cfg.CaptureReviewScale=0;Changed(false);});reset.Foreground=accentBrush;DockPanel.SetDock(reset,Dock.Right);section.Children.Add(reset);var heading=Text("Per-element overrides",15);heading.FontWeight=FontWeights.SemiBold;section.Children.Add(heading);page.Children.Add(section);
