,2);line.Children.Add(follow);input=new TextBox{Text=Math.Round(SurfaceScale(surface)*100).ToString("0"),Foreground=follows?mutedBrush:ink,Background=cardBrush,CaretBrush=ink,BorderBrush=panelBrush,BorderThickness=new Thickness(1),IsEnabled=!follows,Opacity=follows?.5:1,MaxLength=5,ToolTip=follows?"Using global scale":"Enter any value from 70 to 150"};StyleScaleInput(input);Action commit=()=>{double value;if(Double.TryParse(input.Text.Trim().TrimEnd('%'),out value)){double next=Clamp(value/100,.7,1.5);if(Math.Abs(SurfaceOverride(surface)-next)>.0001){SetSurfaceScale(surface,next);Changed(false);}}else input.Text=Math.Round(SurfaceScale(surface)*100).ToString("0");};input.LostKeyboardFocus+=delegate{if(input.IsEnabled)commit();};input.KeyDown+=delegate(object sender,KeyEventArgs e){if(e.Key==Key.Enter&&input.IsEnabled){commit();e.Handled=true;}};Grid.SetColumn(input,3);line.Children.Add(input);page.Children.Add(line);page.Children.Add(new Border{Height=1,Background=cardBrush});}
 } FrameworkElement Pane(Action body){var old=page;var panel=new StackPanel();page=panel;body();page=old;return panel;}
 void Select(string label,string[] values,string current,Action<string> change,bool enabled=true){page.Children.Add(Text(label,12,mutedBrush));string display=label=="Date & time format"?DateTime.Now.ToString(current):current;var combo=Action(display+"   ⌄",()=>{});combo.HorizontalContentAlignment=HorizontalAlignment.Left;combo.Margin=new Thickness(0,8,0,16);combo.IsEnabled=enabled;combo.Opacity=enabled?1:.55;var menu=new ContextMenu();ThemeContextMenu(menu);foreach(string value in values){string selected=value;var item=new MenuItem{Header=label=="Date & time format"?DateTime.Now.ToString(value):value};item.Click+=delegate{combo.Content=(label=="Date & time format"?DateTime.Now.ToString(selected):selected)+"   ⌄";change(selected);};menu.Items.Add(item);}combo.Click+=delegate{menu.PlacementTarget=combo;menu.Placement=PlacementMode.Bottom;menu.IsOpen=true;};page.Children.Add(combo);}
 void AppMenu(Button b,AppEntry entry){var menu=new ContextMenu();ThemeContextMenu(menu);Action fill=()=>{menu.Items.Clear();foreach(bool dockPin in new[]{true,false}){bool d=dockPin;var list=d?cfg.DockPins:cfg.StartPins;bool has=list.Any(x=>String.Equals(x.Target,entry.Target,StringComparison.OrdinalIgnoreCase));var item=new MenuItem{Header=(has?"Unpin from ":"Pin to ")+(d?"taskbar":"Start menu")};item.Click+=delegate{SetAppPin(entry,d,!has);};menu.Items.Add(item);}};fill();menu.Opened+=delegate{appMenuOpen=true;fill();};menu.Closed+=delegate{appMenuOpen=false;lastHover=DateTime.Now;};b.ContextMenu=menu;}
 void SetAppPin(AppEntry entry,bool taskbar,bool value){var list=taskbar?cfg.DockPins:cfg.StartPins;list.RemoveAll(x=>String.Equals(x.Target,entry.Target,StringComparison.OrdinalIgnoreCase));if(taskbar)cfg.PinnedOrder.RemoveAll(x=>String.Equals(x,entry.Target,StringComparison.OrdinalIgnoreCase));if(value){list.Add(entry);if(taskbar)cfg.PinnedOrder.Add(entry.Target);}SaveConfig();RefreshPinnedMenu();if(launcher!=null)DrawLauncher();}
