nce.Stop();if(appsSearch==search&&activeTab=="Apps")fill();};search.Unloaded+=delegate{debounce.Stop();};search.PreviewKeyDown+=delegate(object sender,KeyEventArgs e){if(e.Key==Key.Enter){debounce.Stop();OpenTopSearchResult();e.Handled=true;return;}bool alt=(Keyboard.Modifiers&ModifierKeys.Alt)!=0||e.Key==Key.LeftAlt||e.Key==Key.RightAlt||e.Key==Key.System;if(alt){if(!appSettingsSearch){appSettingsSearch=true;fill();}string typed=SearchKeyText(e);if(typed.Length>0){InsertSearchText(search,typed);e.Handled=true;}else if((e.Key==Key.Back||e.SystemKey==Key.Back)&&search.Text.Length>0){int at=Math.Max(0,search.SelectionStart-1);search.Text=search.Text.Remove(at,1);search.SelectionStart=at;e.Handled=true;}}else if(appSettingsSearch&&search.Text.Length==0&&e.Key!=Key.LeftCtrl&&e.Key!=Key.RightCtrl&&e.Key!=Key.LeftShift&&e.Key!=Key.RightShift){appSettingsSearch=false;fill();}};search.TextChanged+=delegate{appQuery=search.Text.Trim();appPage=0;placeholder.Visibility=search.Text.Length==0?Visibility.Visible:Visibility.Collapsed;debounce.Stop();debounce.Start();};fill();EnsureAppCatalogRefresh();}
