 void AppResults(){var pinned=DockEntries().Concat(cfg.StartPins).Where(MatchesApp).GroupBy(x=>x.Target,StringComparer.OrdinalIgnoreCase).Select(g=>g.First()).ToList();page.Children.Add(Card("☆  Pinned   "+pinned.Count,()=>{var tiles=new UniformGrid{Columns=6};foreach(var item in pinned){var entry=item;var button=Action(entry.Name,()=>OpenApp(entry));button.Height=78;button.Padding=new Thickness(6);var stack=new StackPanel();var icon=new Image{Width=32,Height=32,Margin=new Thickness(0,0,0,7)};QueueIcon(icon,entry.Target);stack.Children.Add(icon);var label=Text(entry.Name,11);label.TextAlignment=TextAlignment.Center;label.TextWrapping=TextWrapping.NoWrap;label.TextTrimming=TextTrimming.CharacterEllipsis;stack.Children.Add(label);button.Content=stack;AppMenu(button,entry);tiles.Children.Add(button);}page.Children.Add(tiles);if(pinned.Count==0)page.Children.Add(Text("No pinned apps",12,mutedBrush));}));page.Children.Add(Card("",()=>{var heading=new DockPanel{Margin=new Thickness(0,0,0,12)};var sorts=new StackPanel{Orientation=Orientation.Horizontal,HorizontalAlignment=HorizontalAlignment.Right};foreach(string sort in new[]{"Name","Recent","Most used"}){string key=sort;var b=Action(sort,()=>{appSort=key;cfg.AppSort=key;SaveConfig();DrawLauncher();},appSort==sort);b.ToolTip=sort=="Most used"?"Apps launched most often through Awl":"Sort applications";sorts.Children.Add(b);}DockPanel.SetDock(sorts,Dock.Right);heading.Children.Add(sorts);heading.Children.Add(Text("▦  All apps   "+catalog.Count(MatchesApp),13));page.Children.Add(heading);var matched=OrderedAppResults().ToList();int pages=Math.Max(1,(matched.Count+19)/20);appPage=Math.Min(appPage,pages-1);var navigation=new DockPanel();navigation.Children.Add(Action("‹",()=>{appPage=Math.Max(0,appPage-1);DrawLauncher();}));navigation.Children.Add(Text((appPage+1)+" / "+pages,12,mutedBrush));navigation.Children.Add(Action("›",()=>{appPage=Math.Min(pages-1,appPage+1);DrawLauncher();}));page.Children.Add(navigation);var list=new