 void ApplyModules(){if(moduleViews==null)return;double toolbarScale=SurfaceScale("Top toolbar");foreach(var view in moduleViews.Values){var parent=view.Parent as Panel;if(parent!=null)parent.Children.Remove(view);else{var owner=view.Parent as ContentControl;if(owner!=null)owner.Content=null;}}var grid=new Grid();for(int i=0;i<3;i++)grid.ColumnDefinitions.Add(new ColumnDefinition());foreach(string side in new[]{"Left","Center","Right"}){var panel=new StackPanel{Orientation=Orientation.Horizontal,HorizontalAlignment=side=="Left"?HorizontalAlignment.Left:side=="Right"?HorizontalAlignment.Right:HorizontalAlignment.Center,Margin=new Thickness(12,0,12,0)};Grid.SetColumn(panel,side=="Left"?0:side=="Center"?1:2);grid.Children.Add(panel);foreach(string name in cfg.ModuleOrder.Distinct()){if(!moduleViews.ContainsKey(name)||ModuleSide(name)!=side)continue;var view=moduleViews[name];view.LayoutTransform=Math.Abs(toolbarScale-1)<.001?Transform.Identity:new ScaleTransform(toolbarScale,toolbarScale);view.Margin=new Thickness(cfg.TopItemSpacing*toolbarScale/2,0,cfg.TopItemSpacing*toolbarScale/2,0);view.Visibility=cfg.HiddenModules.Contains(name)||(name=="Weather"&&!cfg.ShowWeather)||(name=="Media"&&!cfg.ShowMedia)?Visibility.Collapsed:Visibility.Visible;panel.Children.Add(view);}}top.Content=new Border{CornerRadius=new CornerRadius(cfg.TopRadius),Child=grid,Background=Brushes.Transparent};UpdateSystemLabels();}
 void ModuleRows(){page.Children.Add(Text("drag to reorder · pick a side",11,mutedBrush));foreach(string item in cfg.ModuleOrder.ToArray()){string name=item;var row=new DockPanel{Margin=new Thickness(0,7,0,0)};var controls=new StackPanel{Orientation=Orientation.Horizontal};foreach(string sideName in new[]{"Left","Center","Right"}){string side=sideName;var button=Action(side=="Left"?"≡":side=="Center"?"☰":"≡",()=>{cfg.ModuleSides[name]=side;foreach(var candidate in controls.Children.OfType<Button>()){bool selected=Convert.ToString(candidate.Tag)==side;candidate.Background=selected?accentBrush:cardBrush;candidate.Foreground=selected?new SolidColorBrush(Color.FromRgb(16,37,28)):ink;}Changed(false);},ModuleSide(name)==side);button.Tag=side;button.ToolTip=side;button.Padding=new Thickness(8,4,8,4);controls.Children.Add(button);}controls.Children.Add(Switch("",!cfg.HiddenModules.Contains(name)&&!(name=="Weather"&&!cfg.ShowWeather)&&!(name=="Media"&&!cfg.ShowMedia),v=>{cfg.HiddenModules.Remove(name);if(!v)cfg.HiddenModules.Add(name);if(name=="Weather")cfg.ShowWeather=v;if(name=="Media")cfg.ShowMedia=v;Changed(false);}));DockPanel.SetDock(controls,Dock.Right);row.Children.Add(controls);var handle=Text("⠿",17,mutedBrush);handle.Width=28;handle.Cursor=System.Windows.Input.Cursors.SizeAll;handle.MouseMove+=delegate(object sender,System.Windows.Input.MouseEventArgs e){if(e.LeftButton==System.Windows.Input.MouseButtonState.Pressed)DragDrop.DoDragDrop(handle,"Awl.Module:"+name,DragDropEffects.Move);};DockPanel.SetDock(handle,Dock.Left);row.Children.Add(handle);string glyph=name=="Clock"?"◷":name=="Weather"?"☁":name=="Network"?"⌁":name=="Battery"?"▱":name=="Volume"?"◖":name=="Brightness"?"☀":name=="Bluetooth"?"ᛒ":name=="Notifications"?"♧":name=="Capture"?"▣":name=="Search"?"⌕":name=="Media"?"▷":"♩";row.Children.Add(Text(glyph+"   "+name,13));var border=new Border{Child=row,Background=cardBrush,CornerRadius=new CornerRadius(10),Padding=new Thickness(10,3,8,7),Margin=new Thickness(0